    @Test func automaticNoticesAreNotHumanSelectionOrClipboardEntries() {
        let text = Self.vectors[0]["text"]!.stringValue!
        let notice = ChatItem.userText(UserText(id: "notice", text: text, createdAt: .now, localId: nil, isPending: false))
        let human = ChatItem.userText(UserText(id: "human", text: "Please check the CLI", createdAt: .now, localId: nil, isPending: false))
        let answer = ChatItem.agentText(AgentText(id: "answer", text: "Checking it", isThinking: false, createdAt: .now))
        #expect(!MessageSelection.isSelectable(notice))
        #expect(MessageSelection.clipboardText([human, notice, answer], agentName: "Claude")
            == "**You:**\n\nPlease check the CLI\n\n**Claude:**\n\nChecking it")
        #expect(MessageSelection.clipboardText([notice], agentName: "Claude").isEmpty)
    }

    @Test func recognizesCurrentProducerGrammarAndPreservesUsefulDetails() throws {
        for vector in Self.vectors {
            let text = try #require(vector["text"]?.stringValue)
            let notice = try #require(SessionNotice.parse(text))
            #expect(String(describing: notice.kind) == vector["kind"]?.stringValue)
            #expect(notice.originalText == text)
            if notice.kind == .parentDetached {
                #expect(notice.relatedSessionId == nil)
            } else {
                #expect(notice.relatedSessionId == (notice.kind == .parentLinked ? "parent-456" : "child-123"))
            }
        }
        #expect(SessionNotice.parse(Self.vectors[0]["text"]!.stringValue!)?.relatedSessionTitle == "CLI \"ready\" review")
        #expect(SessionNotice.parse(Self.vectors[0]["text"]!.stringValue!)?.detail == "Checked ready/push.\nNo duplicate notices.")
        #expect(SessionNotice.parse(Self.vectors[1]["text"]!.stringValue!)?.relatedSessionTitle == nil)
        #expect(SessionNotice.parse(Self.vectors[2]["text"]!.stringValue!)?.detail == "API failed\nPlease retry")
        #expect(SessionNotice.parse(Self.vectors[4]["text"]!.stringValue!)?.detail == "Tool: Bash\necho hello\nfrom child")
        #expect(SessionNotice.parse(Self.vectors[10]["text"]!.stringValue!)?.detail == "Folder: /tmp/project\nMachine: Fixture Mac\nCurrent state: working on a turn")
    }

    @Test func humanQuotesUnknownGrammarAndMalformedNoticesStayNormal() {
        let text = Self.vectors[0]["text"]!.stringValue!
        let examples = [
            "Please explain this automatic notice", "> " + text.replacingOccurrences(of: "\n", with: "\n> "),
            "```\n" + text + "\n```", "I received this:\n" + text, text + "\nIs that correct?",
            text.components(separatedBy: "\n").first!,
            text.replacingOccurrences(of: "finished its turn and is now idle, waiting for input", with: "finished a turn"),
            text.replacingOccurrences(of: "send child-123", with: "send some-other-session"),
            text.replacingOccurrences(of: "Child session: \"CLI \"ready\" review\" (id: child-123)", with: "Child session: missing id and malformed title"),
        ]
        for example in examples {
            #expect(SessionNotice.parse(example) == nil)
            let human = ChatItem.userText(UserText(id: "human", text: example, createdAt: .now, localId: nil, isPending: false))
            #expect(MessageSelection.isSelectable(human))
            #expect(MessageSelection.clipboardText([human], agentName: "Claude") == example)
        }
    }

    @Test func pendingToCommittedKeepsNoticeIdentityAndOriginalDespiteDisplayOverride() throws {
        let text = Self.vectors[0]["text"]!.stringValue!
        let record: JSONValue = ["role": "user", "content": ["type": "text", "text": .string(text)], "meta": ["displayText": "preview"]]
        let session = try plainSession()
        let queueRow: JSONValue = ["localId": "notice-local", "content": ["t": "plain", "v": record], "status": "queued", "position": 1, "createdAt": 1000]
        let pending = try #require(PendingMessage.list([queueRow], session: session).first)
        #expect(pending.id == "notice-local" && pending.state == .queued)
        #expect(pending.record == record && pending.text == text)
        let notice = try #require(pending.sessionNotice)
        #expect(notice.originalText == text)
        var transcript = Transcript()
        transcript.addPending(localId: pending.localId, text: pending.text, at: pending.createdAt)
        guard case .userText(let optimistic)? = transcript.items.first else { Issue.record("missing optimistic item"); return }
        #expect(optimistic.sessionNotice == notice)
        transcript.apply([TranscriptMessage(id: "server-notice", seq: 3, localId: pending.localId, createdAt: pending.createdAt, record: record)])
        #expect(transcript.items.count == 1)
        guard case .userText(let committed)? = transcript.items.first else { Issue.record("missing committed item"); return }
        #expect(committed.id == optimistic.id && committed.id == "local:notice-local")
        #expect(!committed.isPending && committed.seq == 3)
        #expect(committed.text == text && committed.sessionNotice == notice)
        let thinking = ChatItem.agentText(AgentText(id: "thinking", text: "checking", isThinking: true, createdAt: .now))
        let rows = ChatRow.rows(from: [thinking, .userText(committed), thinking], working: true)
        #expect(rows.contains { if case .item(.userText(let user)) = $0 { user.id == committed.id && user.sessionNotice == notice } else { false } })
        #expect(!rows.contains { if case .work(let steps, _, _) = $0 { steps.contains(.userText(committed)) } else { false } })
    }

    @Test func attachmentsKeepNormalDisplayAndSelectionInBothQueueAndTranscript() throws {
        let text = Self.vectors[0]["text"]!.stringValue!
        let meta: JSONValue = ["displayText": "my attached notice", "happier": ["kind": "attachments.v1", "payload": ["attachments": [["name": "photo.png", "path": "/tmp/photo.png"]]]]]
        let record: JSONValue = ["role": "user", "content": ["type": "text", "text": .string(text)], "meta": meta]
        let row: JSONValue = ["localId": "file-local", "content": ["t": "plain", "v": record], "status": "queued", "position": 1, "createdAt": 1000]
        let pending = try #require(PendingMessage.list([row], session: plainSession()).first)
        #expect(pending.text == "my attached notice" && pending.sessionNotice == nil)
        #expect(pending.files.map(\.name) == ["photo.png"])
        // The chat projects queued messages into UserText too: even raw notice text with a file
        // stays human content when no displayText was supplied by the sender.
        let rawAttached: JSONValue = ["role": "user", "content": ["type": "text", "text": .string(text)],
                                      "meta": ["happier": meta["happier"]!]]
        let rawRow: JSONValue = ["localId": "raw-file", "content": ["t": "plain", "v": rawAttached], "status": "queued", "position": 2, "createdAt": 1000]
        let queuedRaw = try #require(PendingMessage.list([rawRow], session: plainSession()).first)
        #expect(queuedRaw.text == text && queuedRaw.sessionNotice == nil)
        let queuedItem = UserText(id: UserText.stableId(localId: queuedRaw.localId), text: queuedRaw.text,
                                  createdAt: queuedRaw.createdAt, localId: queuedRaw.localId, isPending: true, files: queuedRaw.files)
        #expect(queuedItem.sessionNotice == nil && MessageSelection.isSelectable(.userText(queuedItem)))
        var transcript = Transcript()
        transcript.apply([TranscriptMessage(id: "file", seq: 1, localId: nil, createdAt: .now, record: record)])
        guard case .userText(let user)? = transcript.items.first else { Issue.record("missing attached item"); return }
        #expect(user.text == "my attached notice" && user.attachments == ["photo.png"] && user.sessionNotice == nil)
        #expect(MessageSelection.isSelectable(.userText(user)))
        let pasted = UserText(id: "pasted", text: text, createdAt: .now, localId: nil, isPending: false, attachments: ["photo.png"])
        #expect(pasted.sessionNotice == nil && MessageSelection.isSelectable(.userText(pasted)))
    }

    private func plainSession() throws -> Session {
        try Session(row: ["id": "session", "seq": 0, "createdAt": 1, "updatedAt": 1, "active": true, "activeAt": 1,
                          "encryptionMode": "plain", "metadata": "{}", "metadataVersion": 1, "agentStateVersion": 0], keys: nil)
    }

}
